def preserve_existing_ai(apps, schema_editor):
    Provider = apps.get_model('system_config', 'AIProvider')
    Key = apps.get_model('system_config', 'AIProviderKey')
    Model = apps.get_model('system_config', 'AIModel')
    for provider in Provider.objects.all():
        if provider.api_key_encrypted:
            Key.objects.get_or_create(provider=provider, name='Primary Key', defaults={'secret_encrypted': provider.api_key_encrypted, 'is_active': True})
        configured = [provider.default_model, *(provider.available_models if isinstance(provider.available_models, list) else [])]
        for model_id in configured:
            if not isinstance(model_id, str) or not model_id.strip() or len(model_id) > 120:
                continue
            Model.objects.get_or_create(provider=provider, model_id=model_id, defaults={
                'display_name': model_id, 'source': 'legacy',
                'is_enabled': provider.is_active and model_id == provider.default_model,
                'max_output_tokens': 1000 if provider.provider_type == 'anthropic' and model_id == provider.default_model else None,
            })


